import axios from 'axios';

function getBaseUrl() {
  const envUrl = process.env.REACT_APP_API_URL || 'http://localhost:5050/api';
  const cleanUrl = envUrl.replace(/\/+$/, '');

  if (cleanUrl.endsWith('/api')) {
    return cleanUrl;
  }

  return `${cleanUrl}/api`;
}

const API_BASE_URL = getBaseUrl();

console.log('Tech Store API Base URL:', API_BASE_URL);

const apiClient = axios.create({
  baseURL: API_BASE_URL,
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json',
  },
});

apiClient.interceptors.request.use(
  (config) => {
    console.log('API Request:', `${config.baseURL}${config.url}`);
    return config;
  },
  (error) => Promise.reject(error)
);

apiClient.interceptors.response.use(
  (response) => response,
  (error) => {
    const errorDetails = {
      message: error.message,
      status: error.response?.status,
      url: error.config?.url,
      baseURL: error.config?.baseURL,
      data: error.response?.data,
    };

    console.error('Tech Store API Error:', errorDetails);

    return Promise.reject(error);
  }
);

export const productApi = {
  searchProducts: async (params = {}) => {
    const safeParams = {
      q: params.q || params.search || 'laptop',
      category: params.category || 'all',
      brand: params.brand || 'all',
      minPrice: params.minPrice || '',
      maxPrice: params.maxPrice || '',
      sort: params.sort || 'relevance',
      limit: params.limit || 24,
    };

    const { data } = await apiClient.get('/products/search', {
      params: safeParams,
    });

    return data;
  },

  getProduct: async (productId) => {
    const { data } = await apiClient.get(`/products/${encodeURIComponent(productId)}`);
    return data;
  },

  getTrending: async (limit = 12) => {
    const { data } = await apiClient.get('/products/trending', {
      params: { limit },
    });

    return data;
  },

  getSuggestions: async (q = '') => {
    const { data } = await apiClient.get('/products/suggestions', {
      params: { q },
    });

    return data;
  },

  getCategories: async () => {
    const { data } = await apiClient.get('/products/categories');
    return data;
  },

  getBrands: async (q = '') => {
    const { data } = await apiClient.get('/products/brands', {
      params: { q },
    });

    return data;
  },

  getRecommendations: async (payload = {}) => {
    const { data } = await apiClient.post('/products/recommendations', payload);
    return data;
  },

  getProviderStatus: async () => {
    const { data } = await apiClient.get('/products/providers');
    return data;
  },
};

export const aiApi = {
  chat: async (message, products = []) => {
    const { data } = await apiClient.post('/ai/chat', {
      message,
      products,
    });

    return data;
  },

  suggest: async (query) => {
    const { data } = await apiClient.post('/ai/suggest', {
      query,
    });

    return data;
  },

  sentiment: async (reviews = []) => {
    const { data } = await apiClient.post('/ai/sentiment', {
      reviews,
    });

    return data;
  },
};

export default apiClient;
